# Contenido de los servicios (texto original conservado y revisado)
SERVICES = [
 dict(slug='corte-tijera', name='Corte a tijera', cat='Estilismo', icon='scissors', image='corte-tijera', title='Su estilo.\nNuestra artesanía.', short='Un corte pensado para su manto, su personalidad y vuestra vida juntos.', intro='Hay cortes que se ven bonitos. Y cortes que, además, se viven cómodos. Encontramos el suyo, tijera a tijera.', detail='El corte empieza mucho antes de coger las tijeras: observamos el manto, hablamos de vuestra rutina y elegimos un acabado que puedas mantener en casa. Shadia trabaja las formas y los volúmenes con paciencia, adaptando el arreglo al perro que tiene delante.', extra='Podemos orientar el acabado hacia el estilo de su raza o buscar una opción más práctica. Si hay nudos, primero valoramos cómo resolverlos sin comprometer su comodidad; conservar la longitud nunca está por encima de su bienestar.', benefits=[('Un estilo propio','Siluetas y acabados adaptados a cada perro.'),('Cómodo cada día','Longitudes compatibles con vuestros paseos y cuidados.'),('Detalle a detalle','Atención especial al rostro, las patas y el acabado.')], recommended='Perros cuyo manto admite un trabajo a tijera, como caniches, bichones y otros mantos de crecimiento continuo. También para arreglos de contorno, siempre tras valorar el pelo y su estado.', steps=[('Nos conocemos','Revisamos el pelo y comentamos el acabado deseado.'),('Preparamos el manto','Baño, secado y preparación según sus necesidades.'),('Damos forma','Corte progresivo, con pausas si las necesita.'),('Os contamos cómo cuidarlo','Repasamos el resultado y la rutina entre visitas.')], faq=[('¿Puedo llevar una foto de referencia?','Sí. Nos ayuda a entender el estilo que te gusta. Te explicaremos qué se puede adaptar a su tipo de pelo y al mantenimiento que quieras hacer.'),('¿Y si tiene muchos nudos?','Valoramos su proximidad a la piel y la tolerancia del perro. Si desenredarlos supone tirones o molestias, buscamos juntos una alternativa más cómoda.'),('¿Cuánto dura la cita?','Depende del tamaño, la cantidad de pelo y su comportamiento. Al reservar te orientamos y reservamos el tiempo que necesita, sin fijar una duración igual para todos.')]),
 dict(slug='stripping', name='Stripping', cat='Estilismo', icon='hand-index', image='stripping', title='El carácter de\nsu pelo duro.', short='Trabajo manual para respetar la textura natural del manto.', intro='Una técnica precisa para renovar el pelo maduro y cuidar la identidad de los mantos duros.', detail='El stripping consiste en retirar de forma selectiva el pelo maduro que está preparado para desprenderse. Se realiza por zonas, valorando la textura y el ciclo del manto antes de decidir cuánto trabajar en cada visita.', extra='En Pelucans adaptamos la sesión a la tolerancia del perro. No todos los mantos ni todas las pieles están listos para esta técnica: Shadia revisa el estado del pelo y te explica qué mantenimiento tiene sentido en su caso.', benefits=[('Textura natural','Un trabajo específico para mantos de pelo duro.'),('Renovación selectiva','Retirada del pelo maduro, por zonas.'),('Plan de mantenimiento','Organizamos las visitas según la evolución del manto.')], recommended='Razas y cruces de pelo duro, como schnauzer, westie o teckel de pelo duro, cuando la textura, la piel y el estado del manto lo permiten. La raza por sí sola no determina la técnica.', steps=[('Valoramos la textura','Comprobamos si el pelo está listo para trabajarse.'),('Definimos el arreglo','Acordamos las zonas y el objetivo de la sesión.'),('Trabajamos a mano','Retirada selectiva y pausas adaptadas al perro.'),('Planificamos','Te orientamos sobre el siguiente mantenimiento.')], faq=[('¿Todos los schnauzer necesitan stripping?','No necesariamente. La decisión depende del manto, de su historial de cortes y de la tolerancia del perro, además de la raza.'),('¿Se puede hacer después de usar máquina?','Hay que valorar la textura actual y cómo ha cambiado el pelo. En algunos casos la recuperación requiere varias visitas y no se puede garantizar un resultado concreto.'),('¿Cada cuánto se realiza?','No hay una frecuencia única. Depende del crecimiento y de si buscamos un mantenimiento continuo o un arreglo puntual.')]),
 dict(slug='deslanado', name='Deslanado', cat='Manto e higiene', icon='wind', image='deslanado', title='Menos pelo suelto.\nMás comodidad.', short='Retiramos el subpelo suelto respetando la estructura del manto.', intro='Para esos días en los que parece que hay otro perro en el sofá. Cuidamos la muda desde el manto.', detail='El deslanado ayuda a retirar el subpelo que ya se está desprendiendo. Combinamos el trabajo de cepillado con el baño y el secado que necesite cada manto, sin tratar todas las capas de pelo de la misma manera.', extra='Los perros grandes pueden necesitar una sesión larga y tranquila. Reservamos tiempo suficiente y hacemos pausas: retirar más cantidad de pelo nunca justifica insistir sobre una piel sensible.', benefits=[('Menos pelo desprendido','Ayuda a retirar el pelo suelto durante la muda.'),('Manto más ligero','Trabajamos las acumulaciones de subpelo.'),('Respeto por sus capas','Elegimos herramientas y técnica según el manto.')], recommended='Perros de doble capa y mantos con abundante subpelo, como golden retriever, pastor alemán, husky o sus cruces. También perros de pelo corto con muda, con una técnica adecuada a su piel.', steps=[('Revisamos las capas','Localizamos acumulaciones, nudos y zonas sensibles.'),('Baño adaptado','Preparamos el pelo para soltar el subpelo desprendido.'),('Secado y cepillado','Trabajamos por zonas sin insistir en exceso.'),('Rutina en casa','Te mostramos el cepillado más útil entre visitas.')], faq=[('¿Dejará de soltar pelo?','No. La muda es natural. El servicio retira pelo que ya está suelto y ayuda a mantener el manto, pero no elimina el ciclo de muda.'),('¿Es lo mismo que rapar?','No. Deslanar retira subpelo desprendido; rapar acorta el pelo. Valoramos cada manto antes de recomendar cualquier corte.'),('¿Puedo reservar para un perro grande?','Sí. Cuéntanos su tamaño, cantidad de pelo y cómo tolera el secado para organizar una cita con tiempo suficiente.')]),
 dict(slug='ozonoterapia', name='Baño de ozono', cat='Piel y bienestar', icon='water', image='ozonoterapia', title='Un baño con\ncuidado extra.', short='Una opción de cuidado complementario, siempre adaptada a su piel.', intro='Revisamos sus necesidades antes de elegir el baño. La delicadeza empieza por saber qué le conviene.', detail='El lavado de ozono forma parte de los servicios de cuidado de Pelucans. Antes de plantearlo, hablamos contigo sobre la piel de tu perro, sus sensibilidades y cualquier indicación que haya dado su veterinario.', extra='Si hay picor persistente, heridas, alergias o dermatitis, es importante contar primero con una valoración veterinaria. Este baño no sustituye un diagnóstico ni un tratamiento médico, y no prometemos que cure problemas de piel.', benefits=[('Valoración previa','Escuchamos el historial y las indicaciones de cuidado.'),('Sesión adaptada','Ajustamos la experiencia a su comodidad.'),('Cuidado coordinado','Respetamos las pautas de su veterinario.')], recommended='Perros para los que se considere adecuado un cuidado complementario de baño tras revisar su piel. Si existe una enfermedad cutánea o tratamiento activo, consulta primero con su veterinario.', steps=[('Hablamos de su piel','Nos cuentas sensibilidades y tratamientos actuales.'),('Valoramos la sesión','Confirmamos si este servicio es adecuado.'),('Baño con atención','Supervisamos su comodidad durante el proceso.'),('Seguimiento en casa','Te explicamos los cuidados posteriores acordados.')], faq=[('¿Cura la dermatitis o las alergias?','No lo presentamos como una cura. Las alergias y las enfermedades de piel requieren diagnóstico y seguimiento veterinario.'),('¿Puedo reservar si tiene heridas?','Consúltalo antes con su veterinario y avísanos al contactar. Según el caso, convendrá posponer el baño.'),('¿Se combina con otros servicios?','Podemos valorar una sesión conjunta con el cuidado del manto, siempre que sea adecuada para su piel y su tolerancia.')]),
 dict(slug='dermocosmetica', name='Dermocosmética', cat='Piel y bienestar', icon='droplet', image='dermocosmetica', title='Cada piel merece\nsu propio cuidado.', short='Cosmética canina elegida para su piel, su pelo y su rutina.', intro='El producto adecuado cambia la experiencia del baño. Elegimos el cuidado con la misma atención que el corte.', detail='Trabajamos con cosmética profesional de PSH Pro Health y Artero. Champús, acondicionadores, mascarillas y bálsamos no cumplen todos la misma función. Seleccionamos cosmética formulada para perros según las necesidades observadas y el tipo de manto, con aclarado y aplicación cuidadosos.', extra='Cuéntanos si ha reaccionado a algún producto o si utiliza cosmética pautada por su veterinario. Una piel que muestra molestias necesita valoración profesional antes de probar nuevas rutinas.', benefits=[('Selección individual','Productos elegidos según el pelo y la sensibilidad.'),('Mejor manejabilidad','Cuidado del manto para facilitar su mantenimiento.'),('Rutina coherente','Consejos para continuar el cuidado en casa.')], recommended='Mantos que necesitan un cuidado cosmético específico o una rutina de mantenimiento más adecuada. En perros con problemas de piel, trabajamos respetando las instrucciones veterinarias.', steps=[('Escuchamos','Revisamos la rutina actual y posibles sensibilidades.'),('Seleccionamos','Elegimos los productos apropiados al manto.'),('Aplicamos y aclaramos','Prestamos atención a todas las zonas del cuerpo.'),('Te orientamos','Explicamos cómo mantener el resultado en casa.')], faq=[('¿Puedo traer su champú veterinario?','Coméntanos el producto y su pauta antes de la cita para confirmar cómo incorporarlo al servicio.'),('¿Usáis el mismo champú para todos?','La selección se adapta al tipo de pelo y a las necesidades que nos cuentes. No buscamos una única rutina para todos.'),('¿También puedo comprar productos?','Sí, disponemos de productos para el cuidado en casa. Consulta las opciones y la disponibilidad directamente con Shadia.')]),
 dict(slug='bano-manto', name='Baño y cuidado del manto', cat='Manto e higiene', icon='droplet-half', image='bano-manto', title='Limpito, suave\ny a su ritmo.', short='Baño, secado y cepillado con atención a los pequeños detalles.', intro='El placer de volver a abrazarlo recién bañado. Y la tranquilidad de saber que ha estado bien cuidado.', detail='Un buen baño empieza con una revisión del pelo. Observamos los nudos y las zonas delicadas, elegimos los productos y trabajamos el lavado, aclarado y secado con calma, ajustando cada paso a su tolerancia.', extra='El cuidado del manto puede incluir desenredado suave y revisión higiénica de oídos y almohadillas según lo que necesite. Si un nudo no se puede resolver sin molestias, te lo explicamos antes de decidir cómo continuar.', benefits=[('Limpieza a conciencia','Atención al lavado y al aclarado completo.'),('Cepillado amable','Trabajamos el pelo evitando tirones innecesarios.'),('Pequeños cuidados','Valoramos las necesidades de higiene de cada perro.')], recommended='Perros de todos los tamaños y tipos de pelo que necesiten una sesión de higiene. Adaptamos la experiencia a cachorros, perros mayores y perros que aún están aprendiendo a sentirse cómodos en el salón.', steps=[('Bienvenida tranquila','Dejamos que conozca el espacio y revisamos el pelo.'),('A la bañera','Lavado y aclarado con cosmética adecuada.'),('Secamos con calma','Adaptamos el secado y el cepillado a su tolerancia.'),('Últimos detalles','Repasamos el manto y los cuidados que necesita.')], faq=[('¿Con qué frecuencia debería bañarlo?','Depende de su piel, pelo y actividad. Te orientamos al conocerlo, especialmente si tiene indicaciones veterinarias.'),('¿Qué pasa si le asusta el secador?','Avísanos al reservar. Ajustamos el proceso y hacemos pausas, sin prometer que todos los perros tolerarán la misma sesión.'),('¿El corte de pelo está incluido?','El baño y el corte son necesidades distintas. Al reservar concretamos el servicio y su presupuesto para evitar sorpresas.')]),
 dict(slug='corte-unas', name='Corte de uñas', cat='Manto e higiene', icon='gem', image='corte-unas', title='Pequeños detalles.\nPasos más cómodos.', short='Revisión y corte cuidadoso, respetando sus límites.', intro='También cuidamos lo que no se ve a primera vista. Un pequeño gesto de higiene que merece toda nuestra atención.', detail='Revisamos la longitud de las uñas y realizamos un corte prudente, teniendo en cuenta la zona sensible de cada una. La cantidad que se puede recortar cambia de un perro a otro.', extra='Si le cuesta dejarse tocar las patas, trabajamos con paciencia y pausas. Unas uñas muy largas pueden requerir un mantenimiento progresivo. Ante dolor, lesión o una uña dañada, recomendamos consultar con el veterinario.', benefits=[('Corte prudente','Adaptado a la longitud y a la parte sensible.'),('Atención a las patas','Revisión de las uñas, incluidos los espolones.'),('Experiencia gradual','Pausas y manejo amable si lo necesita.')], recommended='Perros cuyas uñas no se desgastan lo suficiente con su actividad diaria. Es especialmente útil revisar también los espolones, que no apoyan igual al caminar.', steps=[('Revisamos','Observamos longitud, estado y sensibilidad.'),('Se familiariza','Dejamos que se acostumbre al contacto en las patas.'),('Recortamos','Avanzamos con pequeños cortes prudentes.'),('Acordamos el mantenimiento','Te orientamos sobre cuándo volver a revisar.')], faq=[('¿Puedo ir solo para las uñas?','Sí. Escríbenos para acordar una cita específica y confirmar disponibilidad.'),('¿Se pueden cortar uñas negras?','Se trabajan con especial prudencia porque la parte sensible resulta menos visible. Valoramos hasta dónde se puede recortar.'),('¿Qué ocurre si están muy largas?','No siempre se pueden acortar hasta la longitud deseada en una sola visita. Podemos proponer un mantenimiento progresivo.')]),
 dict(slug='comida-especializada', name='Alimentación especializada', cat='En casa', icon='basket2', image='comida', title='El cuidado también\nestá en su cuenco.', short='Opciones de alimentación y una conversación para elegir con criterio.', intro='Cuéntanos qué come, qué le gusta y qué necesitas. Te ayudamos a conocer las opciones disponibles.', detail='En Pelucans también encontrarás alimentación especializada para tu mascota. Te explicamos las características de los productos disponibles para que puedas elegir con información y plantear tus dudas.', extra='Si tu perro necesita una dieta por enfermedad, alergia o intolerancia diagnosticada, la elección debe seguir las indicaciones de su veterinario. La orientación en tienda no sustituye una consulta de nutrición veterinaria.', benefits=[('Información clara','Conoce las características de cada opción.'),('Consulta cercana','Pregúntanos por formatos y disponibilidad.'),('Cuidado continuo','Integra la compra en vuestra visita al salón.')], recommended='Familias que quieren conocer la selección de alimentación disponible. Para necesidades clínicas, trae la recomendación veterinaria y consulta la disponibilidad del producto adecuado.', steps=[('Nos cuentas','Edad, alimentación habitual y preferencias.'),('Vemos opciones','Comentamos la selección y el stock disponible.'),('Resolvemos dudas','Revisamos formatos e información del producto.'),('Planificas la compra','Confirmamos precio y disponibilidad contigo.')], faq=[('¿Puedo comprar sin reservar peluquería?','Sí. Escríbenos para consultar el producto y confirmar el mejor momento para recogerlo.'),('¿Tenéis dietas para alergias?','Consulta la disponibilidad concreta. Si hay una alergia diagnosticada, sigue la dieta indicada por su veterinario.'),('¿Se puede encargar un producto?','Pregúntanos por WhatsApp con el nombre, formato y cantidad. Te confirmaremos si podemos conseguirlo y en qué plazo.')]),
 dict(slug='asesoramiento', name='Asesoramiento', cat='En casa', icon='chat-heart', image='asesoramiento', title='Sus cuidados,\nmás fáciles en casa.', short='Consejos prácticos de cepillado, cosmética y mantenimiento.', intro='No necesitas un cajón lleno de cepillos. Necesitas saber cuál usar, cómo y cuándo.', detail='Hablamos de vuestro día a día y te orientamos sobre las herramientas, el cepillado y los cuidados que mejor encajan con su manto. La idea es que salgas con una rutina comprensible y realista.', extra='También podemos ayudarte a preparar su primera visita: cómo acostumbrarlo poco a poco al contacto en las patas, qué información conviene traer y cómo detectar que un cuidado le resulta incómodo.', benefits=[('Consejos concretos','Una rutina pensada para vuestro día a día.'),('Herramientas adecuadas','Aprende qué cepillo tiene sentido para su pelo.'),('Más confianza','Resuelve tus dudas sin tecnicismos.')], recommended='Familias con un cachorro, un perro recién adoptado o un manto que cuesta mantener. También si necesitas revisar tu rutina o entender por qué aparecen nudos entre citas.', steps=[('Escuchamos tus dudas','Nos cuentas qué os resulta más difícil.'),('Revisamos el manto','Vemos qué cuidados necesita realmente.'),('Lo hacemos sencillo','Explicamos herramientas y técnica de cepillado.'),('Acordamos una rutina','Organizamos el mantenimiento entre visitas.')], faq=[('¿Puedo llevar mis cepillos?','Sí. Así podemos comentar cuáles son adecuados y cómo usarlos para su tipo de pelo.'),('¿Me orientáis para la primera cita de un cachorro?','Sí. Cuéntanos su edad y experiencia previa para preparar una visita progresiva y adaptada.'),('¿Puedo preguntar por problemas de piel?','Podemos comentar su cuidado cosmético, pero el picor persistente, las lesiones o la caída anormal de pelo requieren valoración veterinaria.')]),
]
